export enum SupportedDatastores {
    s3 = 's3',
}
/**
 *
 * Access information for datastore-based measurement (S3 ingestion).
 * Customers assume a Enterprise-managed IAM role to write usage records into the shared ingestion prefix.
 * */
export class DatastoreAccessInformation {
    /**
     * Datastore platform. Defaults to `s3`.
     */
    @Matches(
        `^${Object.values(SupportedDatastores)
            .filter((v) => typeof v !== 'number')
            .join('|')}$`,
        'i'
    )
    @IsOptional()
    @ApiProperty({
        enum: SupportedDatastores,
        isArray: false,
        required: false,
        example: 's3',
    })
    public platform?: SupportedDatastores;

    /**
     * Customer AWS account ID trusted to assume the ingestion role.
     * @example "623673123435"
     */
    @IsString()
    @IsNotEmpty()
    @ApiProperty({ example: '623673123435' })
    public accountId: string;

    /**
     * AWS region for the ingestion resources. Defaults to `us-east-1`.
     */
    @IsString()
    @IsOptional()
    @ApiProperty({ required: false, example: 'us-east-1' })
    public region?: string;

    /**
     * IAM role ARN provisioned for this measurement (generated).
     */
    @IsString()
    @IsOptional()
    @ApiProperty({ required: false })
    public iamRoleArn?: string;

    /**
     * External ID required to assume the IAM role (generated).
     */
    @IsString()
    @IsOptional()
    @ApiProperty({ required: false })
    public externalId?: string;

    /**
     * S3 URI prefix for usage ingestion (generated).
     */
    @IsString()
    @IsOptional()
    @ApiProperty({ required: false })
    public ingestion?: string;

    /**
     * S3 URI prefix for the dead-letter queue (generated).
     */
    @IsString()
    @IsOptional()
    @ApiProperty({ required: false })
    public dlq?: string;

    @ApiHideProperty()
    @IsOptional()
    public businessID?: string;

    @ApiHideProperty()
    @IsOptional()
    public measurementId?: string;

    constructor(datastoreAccessInformation: Partial<DatastoreAccessInformation>) {
        if (datastoreAccessInformation) {
            const {
                accountId,
                platform,
                region,
                iamRoleArn,
                externalId,
                ingestion,
                dlq,
                businessID,
                measurementId,
            } = datastoreAccessInformation;
            this.accountId = accountId;
            this.platform = platform ? platform : SupportedDatastores.s3;
            this.region = region ? region : 'us-east-1';
            this.iamRoleArn = iamRoleArn;
            this.externalId = externalId;
            this.ingestion = ingestion;
            this.dlq = dlq;
            this.businessID = businessID;
            this.measurementId = measurementId;
        }
    }

    public static transformer(datastoreAccessInformation: DatastoreAccessInformation, influxPoint: Point) {
        if (datastoreAccessInformation) {
            const { platform, accountId, region, iamRoleArn, externalId, ingestion, dlq } =
                datastoreAccessInformation;
            if (platform) influxPoint.tag('platform', platform);
            if (accountId) influxPoint.tag('accountId', accountId);
            if (region) influxPoint.tag('region', region);
            if (iamRoleArn) influxPoint.tag('iamRoleArn', iamRoleArn);
            if (externalId) influxPoint.tag('externalId', externalId);
            if (ingestion) influxPoint.tag('ingestion', ingestion);
            if (dlq) influxPoint.tag('dlq', dlq);
        }
        return influxPoint;
    }

    public static dbModelToEntity({
        platform,
        accountId,
        region,
        iamRoleArn,
        externalId,
        ingestion,
        dlq,
        businessID,
        measurementId,
    }: {
        [x: string]: any;
    }) {
        return new DatastoreAccessInformation({
            platform: platform || SupportedDatastores.s3,
            accountId,
            region: region || 'us-east-1',
            iamRoleArn,
            externalId,
            ingestion,
            dlq,
            businessID,
            measurementId,
        });
    }

    private static buildTrustPolicy(accountId: string, externalId: string) {
        return JSON.stringify({
            Version: '2012-10-17',
            Statement: [
                {
                    Effect: 'Allow',
                    Principal: {
                        AWS: `arn:aws:iam::${accountId}:root`,
                    },
                    Action: 'sts:AssumeRole',
                    Condition: {
                        StringEquals: {
                            'sts:ExternalId': externalId,
                        },
                    },
                },
            ],
        });
    }

    private static buildRolePolicy(businessID: string) {
        const ingestionBucket = process.env.DB_MEASUREMENT_BUCKET_NAME;
        const dlqBucket = process.env.DB_MEASUREMENT_DLQ_BUCKET_NAME;
        return JSON.stringify({
            Version: '2012-10-17',
            Statement: [
                {
                    Sid: 'IngestionPrefixAccess',
                    Effect: 'Allow',
                    Action: ['s3:PutObject', 's3:GetObject', 's3:AbortMultipartUpload', 's3:ListMultipartUploadParts'],
                    Resource: [`arn:aws:s3:::${ingestionBucket}/${businessID}/*`],
                },
                {
                    Sid: 'IngestionListPrefix',
                    Effect: 'Allow',
                    Action: ['s3:ListBucket'],
                    Resource: [`arn:aws:s3:::${ingestionBucket}`],
                    Condition: {
                        StringLike: {
                            's3:prefix': [`${businessID}/*`],
                        },
                    },
                },
                {
                    Sid: 'DlqPrefixAccess',
                    Effect: 'Allow',
                    Action: ['s3:GetObject', 's3:ListBucket'],
                    Resource: [
                        `arn:aws:s3:::${dlqBucket}`,
                        `arn:aws:s3:::${dlqBucket}/${businessID}/*`,
                    ],
                },
            ],
        });
    }

    public static async setupAccess(dbAccessInformation: DatastoreAccessInformation) {
        const platform = dbAccessInformation.platform || SupportedDatastores.s3;
        const region = dbAccessInformation.region || process.env.AWS_REGION || 'us-east-1';
        const { accountId, businessID, measurementId } = dbAccessInformation;

        if (platform !== SupportedDatastores.s3) {
            throw new BadRequestException(`Unsupported datastore platform: ${platform}`);
        }
        if (!accountId || !businessID || !measurementId) {
            throw new BadRequestException('accountId, businessID, and measurementId are required for datastore setup');
        }

        const externalId = dbAccessInformation.externalId || uuidv4();
        const roleName = `datastore-${businessID}-${measurementId}`;
        const iam = new IAMClient({ region: process.env.AWS_REGION || region });

        try {
            const createRoleResponse = await iam.send(
                new CreateRoleCommand({
                    RoleName: roleName,
                    AssumeRolePolicyDocument: DatastoreAccessInformation.buildTrustPolicy(accountId, externalId),
                    Description: `Enterprise datastore ingestion role for business ${businessID} measurement ${measurementId}`,
                })
            );

            await iam.send(
                new PutRolePolicyCommand({
                    RoleName: roleName,
                    PolicyName: `${roleName}-policy`,
                    PolicyDocument: DatastoreAccessInformation.buildRolePolicy(businessID),
                })
            );

            const ingestionBucket = process.env.DB_MEASUREMENT_BUCKET_NAME;
            const dlqBucket = process.env.DB_MEASUREMENT_DLQ_BUCKET_NAME;

            dbAccessInformation.platform = platform;
            dbAccessInformation.region = region;
            dbAccessInformation.externalId = externalId;
            dbAccessInformation.iamRoleArn = createRoleResponse.Role?.Arn;
            dbAccessInformation.ingestion = `s3://${ingestionBucket}/${businessID}/`;
            dbAccessInformation.dlq = `s3://${dlqBucket}/${businessID}/`;

            return dbAccessInformation;
        } catch (e) {
            if (e?.name === 'MalformedPolicyDocument' || e?.Code === 'MalformedPolicyDocument') {
                throw new BadRequestException(`accountId: ${accountId} is invalid`);
            }
            throw e;
        }
    }

    public static async updateAccess(dbAccessInformation: DatastoreAccessInformation) {
        const { accountId, iamRoleArn, externalId, region } = dbAccessInformation;
        if (!accountId || !iamRoleArn || !externalId) {
            throw new BadRequestException('accountId, iamRoleArn, and externalId are required to update datastore access');
        }

        const roleName = iamRoleArn.split('/').pop();
        const iam = new IAMClient({ region: process.env.AWS_REGION || region || 'us-east-1' });

        try {
            await iam.send(
                new UpdateAssumeRolePolicyCommand({
                    RoleName: roleName,
                    PolicyDocument: DatastoreAccessInformation.buildTrustPolicy(accountId, externalId),
                })
            );
            return dbAccessInformation;
        } catch (e) {
            if (e?.name === 'MalformedPolicyDocument' || e?.Code === 'MalformedPolicyDocument') {
                throw new BadRequestException(`accountId: ${accountId} is invalid`);
            }
            throw e;
        }
    }
}

