     */
    static normalizeSourceKey(s3Key: string): string {
        if (!s3Key) {
            return s3Key;
        }
        let key = s3Key;
        if (key.startsWith('s3://')) {
            const withoutScheme = key.slice('s3://'.length);
            const slashIndex = withoutScheme.indexOf('/');
            key = slashIndex >= 0 ? withoutScheme.slice(slashIndex + 1) : '';
        }
        if (key.startsWith('/')) {
            key = key.slice(1);
        }
        return key;
    }

    /**
     * Publish a failed usage record to the configured DLQ bucket.
     * DLQ object key mirrors the source key with a `.message.text` suffix.
     */
    static async publishFailureToDLQ({
        message,
        s3Key,
        error,
        metadata,
